export function isProcessAlive(pid: number): boolean {
  if (pid <= 1) return false
  try {
    process.kill(pid, 0)
    return true
  } catch {
    return false
  }
}

/** `D`: los valores únicos de `values`, en su primer orden de aparición. */
function dedupe<T>(values: readonly T[]): T[] {
  return [...new Set(values)]
}

